export const meta = {
  name: 'orbyt-stage4-integrate',
  description: 'Verify every ORBYT page against live data in the browser, review across quality dimensions, and fix what is found',
  phases: [
    { title: 'Verify', detail: 'one agent per page drives the real app in the browser and fixes defects' },
    { title: 'Audit', detail: 'cross-cutting reviews: real-data integrity, security/Vercel, visual quality, performance' },
  ],
}

const COMMON = `You are working on ORBYT, a real-data Solana trading terminal, in the current repository root (Next.js 16, React 19, TypeScript strict, Tailwind v4). A dev server is ALREADY RUNNING at http://localhost:3000 (do not start another; if it is down, start it with preview_start {name:'orbyt-dev'}). Use the built-in browser tools (mcp__Claude_Browser__*: navigate, read_page, get_page_text, computer screenshot/click/type, read_console_messages, read_network_requests, javascript_tool for inspection only, resize_window) to drive the REAL app with LIVE data.

Read first: AGENTS.md, docs/REQUIREMENTS.md (owner spec), PROGRESS.md, docs/DESIGN_BRIEF.md. Owner's latest feedback (highest priority): less "AI-looking", faster, stronger connections, more trustworthy look, Axiom-style trade panel, TradingView charting workflow, clean font (Inter), a working tracker, and "every memecoin there is" on Discover. The deposit address (src/config/site.ts) is central and read-only: never add an edit path.

Rules: real data only (never fabricate; unknown → "—"); no secrets in client code; keep exported APIs stable; fix defects directly in the code (any file), keeping changes minimal and consistent with the codebase; after edits run \`npx tsc --noEmit\`, \`npx eslint <files>\` and relevant \`npx vitest run\`; reload the page and re-verify. No git commands, no npm install, no deployment. Report precisely what you verified (with concrete observed values, e.g. token symbols, prices, counts, timings) and what you fixed.`

const VERIFY_SCHEMA = {
  type: 'object',
  properties: {
    page: { type: 'string' },
    verified: { type: 'array', items: { type: 'string' }, description: 'Concrete observations with real values' },
    defects_fixed: { type: 'array', items: { type: 'object', properties: { file: { type: 'string' }, issue: { type: 'string' } }, required: ['file', 'issue'] } },
    remaining: { type: 'array', items: { type: 'string' } },
    console_errors: { type: 'array', items: { type: 'string' } },
    verification: { type: 'string' },
  },
  required: ['page', 'verified', 'defects_fixed', 'remaining', 'console_errors', 'verification'],
}

const PAGES = [
  { key: 'discover', spec: `Verify /discover and /watchlist. Check: the table fills with real tokens and grows to a large universe (hundreds of tokens across sources, deduped; the "Loaded N tokens · sources" line); list tabs (Trending, Top volume, Organic, New, Gainers) and windows (5m/1h/6h/24h) all work; sorting on every numeric column (undefined last); filters popover; price cells flash on change over 60 s of polling; row click and cmd/ctrl-click behaviour; star adds to /watchlist and the watchlist page renders and refreshes; GeckoTerminal attribution present; no console errors; network tab shows polling within budgets (count GeckoTerminal requests per minute ≤ 8, Jupiter ≤ 4 per 10 s); first paint shows skeletons instantly; scroll performance smooth with hundreds of rows (virtualized or capped). Test at 1440, 1024 and 390 px widths.` },
  { key: 'pulse', spec: `Verify /pulse. Check: New Pairs receives live PumpPortal creates within ~30 s (LIVE badge), cards show symbol/name/age ticking/MC (USD from marketCapSol × SOL price)/dev buy/progress ring; Final Stretch lists bonding curves sorted by on-chain progress (values like 63.2%) refreshed every few seconds; Migrated fills within a few minutes (watch ≥ 3 min) or shows an honest empty state; hover pauses insertion with a queued count; filters work; column headers show counts; clicking a card opens /trade/[mint]; three columns fill the viewport height at 1440 px (no wasted space) and become a column switcher at 390 px; no console errors; PumpPortal socket reconnects if you simulate offline (javascript_tool: dispatch offline/online events is fine).` },
  { key: 'trade', spec: `Verify /trade/[mint] with THREE real tokens: (1) a graduated pump.fun token from Pulse Migrated or Discover New, (2) a large token like PENGU 2zMMhcVQEXDtdE6vsFS7S7D5oUodfJHE8vd1gnBouauv, (3) a bonding-curve token from Pulse New Pairs. Check: header shows real metadata/price/MC/liquidity/volume; the TradingView Lightweight Chart renders real candles (compare last close to the header price), interval switching works (1m–1D native; 1s/5s/15s derived from trades with the "Built from N real trades" label or an honest empty state), crosshair legend, price/MC toggle, log/linear, reset, go-to-realtime, zoom persists across refresh, attribution logo visible; Trades tab shows real transactions (Solscan links resolve to the same signature; wallet links go to /wallet), new trades appear/flash over 60 s; Holders/Pools/Info tabs; risk card; launchpad card with on-chain progress for the bonding token; the Axiom-style trade panel: Buy/Sell, Market/Limit, presets, slippage presets, live quote updates every ~10 s with real Jupiter numbers (outAmount, impact, route, router label), the Buy/Sell button opens the Jupiter deep link in a new tab with correct mints; no console errors; page stacks correctly at 390 px; first paint fast (chart lazy-loaded).` },
  { key: 'wallet-tracker', spec: `Verify /wallet/[address] and /tracker with a REAL active wallet: take a wallet address from a recent trade on a busy token page (/trade/2zMMhcVQEXDtdE6vsFS7S7D5oUodfJHE8vd1gnBouauv Trades tab). Check /wallet: SOL balance and holdings appear with prices where available (unpriced count honest), Activity tab lists real parsed transactions with correct kinds and Solscan links, "Load older" works, PnL tab shows deterministic FIFO results with coverage banner/caveats and per-token audit signatures, freshness badges. Check /tracker: add that wallet (validation for bad input), the feed backfills within seconds and shows live/polling status, entries have kind/token/amount/USD est/time/tx link, rename/remove work, empty state when none tracked, filters. Add a second wallet and confirm both feeds merge newest-first. Test at 390 px. No console errors.` },
  { key: 'shell', spec: `Verify the global shell on every page: header search ("/" focuses; typing "pengu" shows real hits with MC/liquidity; pasting a mint offers "Open token", pasting a wallet offers "Open wallet"; keyboard navigation; Esc closes), SOL price chip updates, stream status popover shows PumpPortal/Solana WS/provider health honestly, Deposit dialog shows the fixed central address 8dbTV2UQXUbhAjpQ8Hf9mcpuJX7LaBWs3FDAqC2rTfc3 with QR and copy (NO edit control anywhere), status bar attribution, 404 page, error boundary fallback (temporarily break nothing — inspect code paths instead), mobile header at 390 px, keyboard focus rings, no layout shift on load. Also verify typography is Inter everywhere (computed font-family) and no page uses other fonts.` },
]

const AUDITS = [
  { key: 'real-data', spec: `AUDIT: real-data integrity across the whole codebase (src/**). Grep for and eliminate: hardcoded token lists, Math.random in non-test code paths that affect displayed data, placeholder numbers, "demo"/"mock"/"sample" data, fallback values that fabricate (e.g. || 0 on market fields), "LIVE" labels on indexed sources, fake timestamps (Date.now() presented as block time), MC computed from assumed supply without a real supply source. Verify every formatter renders "—" for undefined. Check that trade-derived candles never synthesize bars and that applyLiveTick never invents an open. Fix defects and add tests.` },
  { key: 'security-vercel', spec: `AUDIT: security and Vercel readiness. Verify no secret reaches the client (grep NEXT_PUBLIC_, process.env usage in client components, API keys in URLs logged/returned), every route validates input (addresses, enums, limits, signature format) and never proxies arbitrary URLs, error responses never include upstream URLs, CDN cache headers sensible, 'server-only' on server modules, external links use rel="noopener noreferrer", no dangerouslySetInnerHTML with provider data, CSP-safe (no inline event handlers from data), vercel.json + package engines correct, next.config headers, no dependency on local files, .env.example complete and accurate versus actual process.env reads (list every env var read in code and ensure each is documented). Run \`npm run build\` and fix any build error or warning that matters.` },
  { key: 'visual', spec: `AUDIT: visual quality and trust ("no AI-looking website; legit big DEX"). Drive the app in the browser at 1440 and 390 px and screenshot every page. Fix: inconsistent spacing/radii/borders, mismatched font sizes, misaligned numeric columns (must be right-aligned tabular), color misuse (brand purple only for active/primary; up/down only for direction), any gradient/glow/emoji/marketing copy/exclamation marks, empty states that look like errors, missing hover/focus states, illegible contrast, wasted vertical space (panels should fill the viewport on desktop), inconsistent icon sizes. Ensure the header, status bar, tables, cards and dialogs share one visual language. Keep the Inter typography. Make targeted CSS/JSX fixes; do not redesign from scratch.` },
  { key: 'performance', spec: `AUDIT: performance and connection resilience. In the browser measure: time to first content on /discover, /pulse, /trade/[mint]; count network requests per minute per provider on each page (must respect keyless budgets: GeckoTerminal ≤ 8/min, Jupiter ≤ 4 per 10 s, DEX Screener modest); check no request waterfalls on the trade page (pool-independent requests start immediately; chart library loads lazily); confirm React Query keeps last good data when a request fails (simulate by blocking a host with javascript_tool fetch override? — instead inspect code and provoke a 429 by rapid navigation) and that freshness badges show delayed state honestly; confirm streams reconnect after offline/online events; check for memory leaks (intervals/subscriptions cleared on unmount by navigating between pages 10× and checking active timers via javascript_tool). Fix defects (memoization, cadence, dedupe, cleanup).` },
]

phase('Verify')
const verified = await parallel(PAGES.map((p) => () => agent(`${COMMON}\n\nPAGE VERIFICATION: ${p.key}\n${p.spec}`, { label: `verify:${p.key}`, phase: 'Verify', schema: VERIFY_SCHEMA })))

phase('Audit')
const audits = await parallel(AUDITS.map((a) => () => agent(`${COMMON}\n\n${a.spec}\n\nContext from page verification (already fixed items may not need re-fixing):\n${JSON.stringify(verified.filter(Boolean).map((v) => ({ page: v.page, remaining: v.remaining })), null, 1).slice(0, 6000)}`, { label: `audit:${a.key}`, phase: 'Audit', schema: VERIFY_SCHEMA })))

return { verified: verified.filter(Boolean), audits: audits.filter(Boolean) }
